\setlength{\tabcolsep}{3pt}
\begin{tabular}{@{}lccc@{}}
\toprule
& \textbf{SIGMA} & \textbf{He+ '25} & \textbf{This work} \\
\midrule
Setting & Recursive & Continual & Recursive \\
